/**
 * powerIqClient.ts
 * ----------------------------------------------------------------------------
 * Centralized HTTP client for PowerIQ-AI microservices.
 * Injects Bearer token, handles automatic refresh on 401,
 * and routes to the appropriate microservice base URLs.
 * ----------------------------------------------------------------------------
 */

import axios, { AxiosError, InternalAxiosRequestConfig } from "axios";
import { storage } from "../services/storage";
import {
  CONFIG,
  AUTH_BASE_URL,
  TELEMETRY_BASE_URL,
  KPI_BASE_URL,
  DEVICE_BASE_URL,
  COMPANY_BASE_URL,
  POLICY_BASE_URL,
  BILLS_BASE_URL,
  ALERT_BASE_URL,
} from "../config/constants";
import { authClient } from "./authClient";
import { RefreshTokenResponse } from "../types/auth";

export const SERVICE_BASES = {
  AUTH: AUTH_BASE_URL,
  TELEMETRY: TELEMETRY_BASE_URL,
  KPI: KPI_BASE_URL,
  DEVICE: DEVICE_BASE_URL,
  COMPANY: COMPANY_BASE_URL,
  POLICY: POLICY_BASE_URL,
  BILLS: BILLS_BASE_URL,
  ALERT: ALERT_BASE_URL,
} as const;

export const powerIqClient = axios.create({
  timeout: 30000,
  headers: {
    "Content-Type": "application/json",
    Accept: "application/json",
  },
});

let isRefreshing = false;
let failedQueue: Array<{
  resolve: (token: string) => void;
  reject: (err: any) => void;
}> = [];

const processQueue = (error: any, token: string | null = null) => {
  failedQueue.forEach((promise) => {
    if (error) {
      promise.reject(error);
    } else {
      promise.resolve(token!);
    }
  });
  failedQueue = [];
};

powerIqClient.interceptors.request.use(
  async (config: InternalAxiosRequestConfig) => {
    const token = await storage.getItem(CONFIG.STORAGE_KEYS.ACCESS_TOKEN);
    if (token && !config.headers.Authorization) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

powerIqClient.interceptors.response.use(
  (response) => response,
  async (error: AxiosError) => {
    const originalRequest = error.config as InternalAxiosRequestConfig & {
      _retry?: boolean;
    };

    if (error.response?.status === 401 && !originalRequest._retry) {
      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        })
          .then((token) => {
            originalRequest.headers.Authorization = `Bearer ${token}`;
            return powerIqClient(originalRequest);
          })
          .catch((err) => Promise.reject(err));
      }

      originalRequest._retry = true;
      isRefreshing = true;

      try {
        const refreshToken = await storage.getItem(CONFIG.STORAGE_KEYS.REFRESH_TOKEN);
        if (!refreshToken) {
          throw new Error("No refresh token available");
        }

        const refreshRes = await authClient.post<RefreshTokenResponse>(
          "/auth/refresh-token",
          { refreshToken }
        );

        const newAccessToken =
          (refreshRes.data as any)?.data?.accessToken ||
          (refreshRes.data as any)?.data?.token ||
          refreshRes.data?.accessToken ||
          (refreshRes.data as any)?.token;

        if (!newAccessToken) {
          throw new Error("Refresh response did not contain new access token");
        }

        await storage.setItem(CONFIG.STORAGE_KEYS.ACCESS_TOKEN, newAccessToken);
        powerIqClient.defaults.headers.common["Authorization"] = `Bearer ${newAccessToken}`;
        originalRequest.headers.Authorization = `Bearer ${newAccessToken}`;

        processQueue(null, newAccessToken);
        return powerIqClient(originalRequest);
      } catch (refreshErr) {
        processQueue(refreshErr, null);
        await storage.removeItem(CONFIG.STORAGE_KEYS.ACCESS_TOKEN);
        await storage.removeItem(CONFIG.STORAGE_KEYS.REFRESH_TOKEN);
        return Promise.reject(refreshErr);
      } finally {
        isRefreshing = false;
      }
    }

    return Promise.reject(error);
  }
);

export function joinUrl(base: string, path: string): string {
  const cleanBase = String(base || "").replace(/\/+$/, "");
  const cleanPath = String(path || "").replace(/^\/+/, "");
  return `${cleanBase}/${cleanPath}`;
}
