interface ProductSecScreenProps {
  onBack?: () => void;
}

type SortOption =
  | "latest_desc"
  | "product_id_asc"
  | "product_id_desc"
  | "name_asc"
  | "name_desc"
  | "sec_asc"
  | "sec_desc";

const SORT_LABELS: Record<SortOption, string> = {
  latest_desc: "Latest Production First",
  product_id_asc: "Product ID: Increasing",
  product_id_desc: "Product ID: Decreasing",
  name_asc: "Product Name: A to Z",
  name_desc: "Product Name: Z to A",
  sec_asc: "SEC: Low to High",
  sec_desc: "SEC: High to Low",
};

export type DatePeriod = "today" | "yesterday" | "this_month" | "all_time" | "custom_date";

const PERIOD_LABELS: Record<DatePeriod, string> = {
  today: "Today",
  yesterday: "Yesterday",
  this_month: "This Month",
  all_time: "All Time",
  custom_date: "Custom Date",
};

function getComputedDateRange(
  period: DatePeriod,
  customFrom?: string,
  customTo?: string
) {
  const now = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  const toYmd = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const toMonthShort = (d: Date) => d.toLocaleString("en-US", { month: "short" });
  const toMonthFull = (d: Date) => d.toLocaleString("en-US", { month: "long" });
  const fmtDisplay = (ymd: string) => {
    const p = ymd.split("-");
    const d2 = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
    return `${d2.getDate()} ${toMonthShort(d2)} ${d2.getFullYear()}`;
  };

  if (period === "today") {
    const ymd = toYmd(now);
    const day = now.getDate();
    const mon = toMonthShort(now);
    const yr = now.getFullYear();
    return {
      from: ymd,
      to: ymd,
      label: "Today",
      rangeText: `${day} ${mon} ${yr} → ${day} ${mon} ${yr}`,
      subText: `${day}th ${toMonthFull(now)} ${yr}, 12:00 am – 11:59 pm`,
    };
  }

  if (period === "yesterday") {
    const yest = new Date(now.getTime() - 86400000);
    const ymd = toYmd(yest);
    const day = yest.getDate();
    const mon = toMonthShort(yest);
    const yr = yest.getFullYear();
    return {
      from: ymd,
      to: ymd,
      label: "Yesterday",
      rangeText: `${day} ${mon} ${yr} → ${day} ${mon} ${yr}`,
      subText: `${day}th ${toMonthFull(yest)} ${yr}, 12:00 am – 11:59 pm`,
    };
  }

  if (period === "this_month") {
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    const startYmd = toYmd(start);
    const endYmd = toYmd(now);
    const mon = toMonthShort(now);
    const yr = now.getFullYear();
    return {
      from: startYmd,
      to: endYmd,
      label: "This Month",
      rangeText: `01 ${mon} → ${pad(now.getDate())} ${mon} ${yr}`,
      subText: `Month of ${toMonthFull(now)} ${yr}`,
    };
  }

  if (period === "custom_date" && customFrom && customTo) {
    const fromDisplay = fmtDisplay(customFrom);
    const toDisplay = fmtDisplay(customTo);
    const sameDay = customFrom === customTo;
    return {
      from: customFrom,
      to: customTo,
      label: `${fromDisplay} → ${toDisplay}`,
      rangeText: `${fromDisplay} → ${toDisplay}`,
      subText: sameDay ? `${fromDisplay}, 12:00 am – 11:59 pm` : `${fromDisplay} to ${toDisplay}`,
    };
  }

  return {
    from: "",
    to: "",
    label: "All Time",
    rangeText: "All Recorded Production Logs",
    subText: "Cumulative historical metrics across all shifts",
  };
}

export const ProductSecScreen: React.FC<ProductSecScreenProps> = () => {
  const navigation = useNavigation<any>();
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Products state
  const [products, setProducts] = useState<any[]>([]);
  const [selectedProductId, setSelectedProductId] = useState<string>("");

  // Date Filter State
  const [datePeriod, setDatePeriod] = useState<DatePeriod>("today");
  const [dateModalVisible, setDateModalVisible] = useState(false);
  // Custom date range
  const [customFrom, setCustomFrom] = useState<string>(""); // YYYY-MM-DD
  const [customTo, setCustomTo] = useState<string>("");     // YYYY-MM-DD
  // During range picking: null=picking from, "from"=from set waiting for to
  const [pickingStep, setPickingStep] = useState<"from" | "to">("from");
  const [showCalendar, setShowCalendar] = useState(false);

  // Calendar navigation state
  const nowRef = new Date();
  const [calYear, setCalYear] = useState(nowRef.getFullYear());
  const [calMonth, setCalMonth] = useState(nowRef.getMonth());

  // Filter & Modals
  const [sortBy, setSortBy] = useState<SortOption>("latest_desc");
  const [sortModalVisible, setSortModalVisible] = useState(false);
  const [productModalVisible, setProductModalVisible] = useState(false);
  const [productSearchQuery, setProductSearchQuery] = useState("");

  // Product specific live metrics
  const [productMetric, setProductMetric] = useState<any>(null);
  const [metricsLoading, setMetricsLoading] = useState(false);

  const computedDate = useMemo(
    () => getComputedDateRange(datePeriod, customFrom, customTo),
    [datePeriod, customFrom, customTo]
  );

  // Build calendar days grid
  const calDaysGrid = React.useMemo(() => {
    const firstDay = new Date(calYear, calMonth, 1).getDay();
    const totalDays = new Date(calYear, calMonth + 1, 0).getDate();
    const days: (number | null)[] = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let d = 1; d <= totalDays; d++) days.push(d);
    return days;
  }, [calYear, calMonth]);

  const MONTHS_SHORT_SEC = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const WEEKDAYS_SEC = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

  // Helper: compare two YYYY-MM-DD strings
  const cmpDate = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;

  const loadData = useCallback(async (force = false) => {
    try {
      if (!force) setLoading(true);
      setError(null);

      const overview = await fetchSecOverview(force);
      let list: any[] = Array.isArray(overview?.products) ? overview.products : [];

      if (!list.length) {
        // Fallback to direct sec product configs
        list = await fetchSecProductConfigs();
      }

      if (list.length > 0) {
        setProducts(list);
        setSelectedProductId((prevId) => {
          if (prevId && list.some((p: any) => String(p.productId || p._id) === prevId)) {
            return prevId;
          }
          const found = list.find((p: any) => String(p.name || p.productName).includes("16-2-30dp")) || list[0];
          return String(found?.productId || found?._id || "");
        });
      } else {
        setProducts([]);
        setSelectedProductId("");
      }
    } catch (err: any) {
      console.warn("Failed to load SEC Overview:", err?.message || err);
      setError(
        err?.response?.data?.message ||
          err?.message ||
          "Unable to load SEC products. Please check your connection."
      );
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Load metrics dynamically when selected product or date period changes
  useEffect(() => {
    if (!selectedProductId) return;

    let cancelled = false;
    const fetchMetrics = async () => {
      try {
        setMetricsLoading(true);
        const params: any = { page: 1, limit: 50 };
        if (computedDate.from && computedDate.to) {
          params.productionDateFrom = computedDate.from;
          params.productionDateTo = computedDate.to;
        }

        const history = await fetchSecProductHistory(selectedProductId, params);
        if (cancelled) return;

        const summary =
          history?.summary ||
          history?.data?.summary ||
          (history?.rows && history.summary) ||
          history?.data ||
          null;
        setProductMetric(summary);
      } catch (err) {
        console.warn("Failed to fetch product history:", err);
        if (!cancelled) setProductMetric(null);
      } finally {
        if (!cancelled) setMetricsLoading(false);
      }
    };

    fetchMetrics();
    return () => {
      cancelled = true;
    };
  }, [selectedProductId, computedDate.from, computedDate.to]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    loadData(true);
  }, [loadData]);

  // Active selected product object
  const activeProduct = useMemo(() => {
    const found = products.find(
      (p) => String(p.productId || p._id) === String(selectedProductId)
    );
    if (found) return found;

    return (
      products[0] || {
        productId: selectedProductId || "—",
        name: "Product",
        productName: "Product",
        size: "0",
        primaryProductUnit: "kg",
        secondaryProductUnit: "mts",
      }
    );
  }, [products, selectedProductId]);

  // Sorted product list for modal
  const sortedProducts = useMemo(() => {
    const list = [...products];
    const q = productSearchQuery.toLowerCase().trim();

    const filtered = list.filter((p) => {
      if (!q) return true;
      const name = String(p.name || p.productName || "").toLowerCase();
      const id = String(p.productId || p._id || "").toLowerCase();
      return name.includes(q) || id.includes(q);
    });

    filtered.sort((a, b) => {
      const aName = String(a.name || a.productName || "");
      const bName = String(b.name || b.productName || "");
      const aId = String(a.productId || a._id || "");
      const bId = String(b.productId || b._id || "");

      switch (sortBy) {
        case "name_asc":
          return aName.localeCompare(bName);
        case "name_desc":
          return bName.localeCompare(aName);
        case "product_id_asc":
          return aId.localeCompare(bId, undefined, { numeric: true });
        case "product_id_desc":
          return bId.localeCompare(aId, undefined, { numeric: true });
        case "sec_asc": {
          const aSec = Number(a.summary?.secPerProductionUnit ?? a.summary?.sec ?? 9999);
          const bSec = Number(b.summary?.secPerProductionUnit ?? b.summary?.sec ?? 9999);
          return aSec - bSec;
        }
        case "sec_desc": {
          const aSec = Number(a.summary?.secPerProductionUnit ?? a.summary?.sec ?? 0);
          const bSec = Number(b.summary?.secPerProductionUnit ?? b.summary?.sec ?? 0);
          return bSec - aSec;
        }
        default:
          return 0;
      }
    });

    return filtered;
  }, [products, productSearchQuery, sortBy]);

  // Formatters
  const formatNum = (v: any, decimals = 3) => {
    if (v === null || v === undefined) return "—";
    const n = Number(v);
    if (!Number.isFinite(n)) return "—";
    return new Intl.NumberFormat("en-IN", {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }).format(n);
  };

  const formatCurrency = (v: any) => {
    if (v === null || v === undefined) return "—";
    const n = Number(v);
    if (!Number.isFinite(n)) return "—";
    return new Intl.NumberFormat("en-IN", {
      style: "currency",
      currency: "INR",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(n);
  };

  // Resolved 9 KPI values for the active product
  const resolvedMetrics = useMemo(() => {
    const p = activeProduct;
    const pId = String(p?.productId || p?._id || selectedProductId || "—");
    const pName = String(p?.name || p?.productName || "Product");

    const summary = productMetric;
    const hasLogs = Number(summary?.logCount || 0) > 0;
    const hasDirectMetrics =
      summary &&
      ((summary.secPerProductionUnit ?? summary.sec) != null ||
        (summary.tec ?? summary.totalEnergy) != null ||
        (summary.primaryProductionQtyEntered ?? summary.productionQtyEntered ?? summary.qtyProduced) != null);

    // Fall back to product's overview summary if specific date has no logs
    const fallbackSummary = p?.summary || (p?.secPerProductionUnit != null ? p : null);
    const activeSummary = hasLogs || hasDirectMetrics ? summary : fallbackSummary;
    const isFallbackToCumulative = !hasLogs && !hasDirectMetrics && Boolean(fallbackSummary);

    const primaryUnit = p?.primaryProductUnit || p?.productUnit || "kg";
    const secondaryUnit = p?.secondaryProductUnit || "mts";

    if (!activeSummary) {
      return {
        productName: pName,
        productId: pId,
        size: p?.size ?? "0",
        primaryUnit,
        secondaryUnit,
        hasData: false,
        isFallbackToCumulative: false,
        primaryQty: null,
        secondaryQty: null,
        wastageQty: null,
        totalQty: null,
        tec: null,
        sec: null,
        tecPerUnit: null,
        totalCost: null,
        costPerUnit: null,
      };
    }

    const primaryQty = activeSummary.primaryProductionQtyEntered ?? activeSummary.productionQtyEntered ?? activeSummary.qtyProduced ?? null;
    const secondaryQty = activeSummary.secondaryProductionQtyEntered ?? null;
    const wastageQty = activeSummary.wastageQty ?? null;
    const totalQty = activeSummary.totalProductionQty ?? (primaryQty !== null && wastageQty !== null ? Number(primaryQty) + Number(wastageQty) : null);
    const tec = activeSummary.tec ?? activeSummary.totalEnergy ?? null;
    const sec = activeSummary.secPerProductionUnit ?? activeSummary.sec ?? null;
    const tecPerUnit = activeSummary.tecPerProductionUnit ?? activeSummary.tecPerUnit ?? null;
    const totalCost = activeSummary.totalCost ?? null;
    const costPerUnit = activeSummary.costPerProductionUnit ?? activeSummary.costPerUnit ?? (primaryQty && totalCost ? Number(totalCost) / Number(primaryQty) : null);

    return {
      productName: pName,
      productId: pId,
      size: p?.size ?? "0",
      primaryUnit,
      secondaryUnit,
      hasData: true,
      isFallbackToCumulative,
      primaryQty: primaryQty !== null ? Number(primaryQty) : null,
      secondaryQty: secondaryQty !== null ? Number(secondaryQty) : null,
      wastageQty: wastageQty !== null ? Number(wastageQty) : null,
      totalQty: totalQty !== null ? Number(totalQty) : null,
      tec: tec !== null ? Number(tec) : null,
      sec: sec !== null ? Number(sec) : null,
      tecPerUnit: tecPerUnit !== null ? Number(tecPerUnit) : null,
      totalCost: totalCost !== null ? Number(totalCost) : null,
      costPerUnit: costPerUnit !== null ? Number(costPerUnit) : null,
    };
  }, [activeProduct, productMetric, selectedProductId, datePeriod]);

  return (
    <View style={styles.container}>
      {/* App Header (Logo + Hamburger) */}
      <AppHeader />

      {/* 2. Date Row (Today ▾ + Date Range Card) */}
      <View style={styles.dateRow}>
        <TouchableOpacity
          style={styles.todayPill}
          activeOpacity={0.8}
          onPress={() => setDateModalVisible(true)}
        >
          <Text style={styles.todayPillText}>{PERIOD_LABELS[datePeriod]}</Text>
          <ChevronDown size={15} color="#2563EB" />
        </TouchableOpacity>

        <TouchableOpacity
          style={styles.calendarCard}
          activeOpacity={0.85}
          onPress={() => setDateModalVisible(true)}
        >
          <Calendar size={17} color="#475569" style={styles.calendarIcon} />
          <View style={styles.calendarTextCol}>
            <Text style={styles.calendarRangeText} numberOfLines={1}>
              {computedDate.rangeText}
            </Text>
            <Text style={styles.calendarSubText} numberOfLines={1}>
              {computedDate.subText}
            </Text>
          </View>
        </TouchableOpacity>
      </View>

      {/* 3. Actions Row (Sort Products + Product Dropdown Box) */}
      <View style={styles.actionsRow}>
        {/* Left: Sort Products Button */}
        <TouchableOpacity
          style={styles.sortButton}
          onPress={() => setSortModalVisible(true)}
          activeOpacity={0.85}
        >
          <Menu size={16} color="#2563EB" />
          <Text style={styles.sortButtonText}>Sort Products</Text>
        </TouchableOpacity>

        {/* Center: Product Selector Card */}
        <TouchableOpacity
          style={styles.productDropdownCard}
          onPress={() => setProductModalVisible(true)}
          activeOpacity={0.85}
        >
          <View style={styles.productTitleRow}>
            <Text style={styles.productDropdownName} numberOfLines={1}>
              {resolvedMetrics.productName}
            </Text>
            <ChevronDown size={16} color="#64748B" />
          </View>
          <Text style={styles.productDropdownSub} numberOfLines={1}>
            Product ID: {resolvedMetrics.productId} • Size: {resolvedMetrics.size}
          </Text>
        </TouchableOpacity>

        {/* Right: 📋 Logs Button */}
        <TouchableOpacity
          style={styles.logsButton}
          onPress={() => {
            navigation.navigate("ProductLogs", {
              productId: resolvedMetrics.productId,
              productName: resolvedMetrics.productName,
              unit: resolvedMetrics.primaryUnit,
              secondaryUnit: resolvedMetrics.secondaryUnit,
            });
          }}
          activeOpacity={0.85}
        >
          <ClipboardList size={15} color="#FFFFFF" />
          <Text style={styles.logsButtonText}>Logs</Text>
        </TouchableOpacity>
      </View>

      {/* 4. Metric Cards Scroll Area */}
      <ScrollView
        style={styles.scroll}
        contentContainerStyle={styles.scrollContent}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            colors={[CONFIG.THEME.primary]}
            tintColor={CONFIG.THEME.primary}
          />
        }
      >
        {loading && !refreshing ? (
          <View style={{ padding: 16 }}>
            <CardSkeleton height={100} />
            <CardSkeleton height={100} />
            <CardSkeleton height={100} />
          </View>
        ) : error ? (
          <ErrorCard title="Error" message={error} onRetry={() => loadData(true)} />
        ) : (
          <View style={styles.tilesContainer}>
            {resolvedMetrics.isFallbackToCumulative && !metricsLoading && (
              <View style={styles.cumulativeBanner}>
                <Info size={16} color="#1D4ED8" style={{ marginTop: 2 }} />
                <View style={{ flex: 1, marginLeft: 8 }}>
                  <Text style={styles.cumulativeBannerTitle}>Cumulative Product Metrics</Text>
                  <Text style={styles.cumulativeBannerSub}>
                    No production logs recorded yet for {computedDate.label.toLowerCase()}. Showing overall cumulative metrics for this product. Tap "Logs" to record today's production.
                  </Text>
                </View>
              </View>
            )}

            {!resolvedMetrics.hasData && !metricsLoading && (
              <View style={styles.noDataBanner}>
                <Info size={16} color="#0284C7" style={{ marginTop: 2 }} />
                <View style={{ flex: 1, marginLeft: 8 }}>
                  <Text style={styles.noDataTitle}>No production logged for this date</Text>
                  <Text style={styles.noDataSub}>
                    Specific energy consumption is calculated from recorded production output. Tap "Logs" to add a production log, or switch to All Time to see historical data.
                  </Text>
                  {datePeriod !== "all_time" && (
                    <TouchableOpacity
                      style={styles.allTimeShortcutBtn}
                      onPress={() => setDatePeriod("all_time")}
                      activeOpacity={0.7}
                    >
                      <Text style={styles.allTimeShortcutText}>View All Time Metrics →</Text>
                    </TouchableOpacity>
                  )}
                </View>
              </View>
            )}

            {/* Row 1: Primary Qty & Secondary Qty */}
            <View style={styles.twoColRow}>
              {/* Primary Production Quantity */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#EBF4FF" }]}>
                  <Factory size={18} color="#2563EB" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>Primary Production Quantity</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.primaryQty !== null
                      ? `${formatNum(resolvedMetrics.primaryQty, 3)} ${resolvedMetrics.primaryUnit}`
                      : "—"}
                  </Text>
                </View>
              </View>

              {/* Secondary Production Quantity */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#ECFDF5" }]}>
                  <Factory size={18} color="#10B981" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>Secondary Production Quantity</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.secondaryQty !== null
                      ? `${formatNum(resolvedMetrics.secondaryQty, 3)} ${resolvedMetrics.secondaryUnit}`
                      : "—"}
                  </Text>
                </View>
              </View>
            </View>

            {/* Row 2: Wastage Quantity (Full Width Card) */}
            <View style={styles.fullWidthCard}>
              <View style={[styles.tileIconCircle, { backgroundColor: "#FEF2F2" }]}>
                <Trash2 size={18} color="#EF4444" />
              </View>
              <View style={styles.tileContent}>
                <Text style={styles.tileLabel}>Wastage Quantity</Text>
                <Text style={styles.tileValue}>
                  {resolvedMetrics.wastageQty !== null
                    ? `${formatNum(resolvedMetrics.wastageQty, 3)} ${resolvedMetrics.primaryUnit}`
                    : "—"}
                </Text>
              </View>
            </View>

            {/* Row 3: Total Quantity & Total Energy Consumption */}
            <View style={styles.twoColRow}>
              {/* Total Quantity */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#EFF6FF" }]}>
                  <Box size={18} color="#2563EB" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>Total Quantity</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.totalQty !== null
                      ? `${formatNum(resolvedMetrics.totalQty, 3)} ${resolvedMetrics.primaryUnit}`
                      : "—"}
                  </Text>
                </View>
              </View>

              {/* Total Energy Consumption */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#FEF9C3" }]}>
                  <Zap size={18} color="#F59E0B" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>Total Energy Consumption</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.tec !== null
                      ? `${formatNum(resolvedMetrics.tec, 3)} kWh`
                      : "—"}
                  </Text>
                </View>
              </View>
            </View>

            {/* Row 4: SEC / unit & TEC / unit */}
            <View style={styles.twoColRow}>
              {/* SEC / unit */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#F3E8FF" }]}>
                  <BarChart2 size={18} color="#8B5CF6" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>SEC / {resolvedMetrics.primaryUnit}</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.sec !== null
                      ? `${formatNum(resolvedMetrics.sec, 4)} kWh/${resolvedMetrics.primaryUnit}`
                      : "—"}
                  </Text>
                </View>
              </View>

              {/* TEC / unit */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#CCFBF1" }]}>
                  <BarChart2 size={18} color="#14B8A6" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>TEC / {resolvedMetrics.primaryUnit}</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.tecPerUnit !== null
                      ? `${formatNum(resolvedMetrics.tecPerUnit, 4)} kWh/${resolvedMetrics.primaryUnit}`
                      : "—"}
                  </Text>
                </View>
              </View>
            </View>

            {/* Row 5: Total Cost & Cost / unit */}
            <View style={styles.twoColRow}>
              {/* Total Cost */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#FFE4E6" }]}>
                  <Coins size={18} color="#F43F5E" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>Total Cost</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.totalCost !== null
                      ? formatCurrency(resolvedMetrics.totalCost)
                      : "—"}
                  </Text>
                </View>
              </View>

              {/* Cost / unit */}
              <View style={styles.tileCard}>
                <View style={[styles.tileIconCircle, { backgroundColor: "#EDE9FE" }]}>
                  <Tag size={18} color="#7C3AED" />
                </View>
                <View style={styles.tileContent}>
                  <Text style={styles.tileLabel}>Cost / {resolvedMetrics.primaryUnit}</Text>
                  <Text style={styles.tileValue}>
                    {resolvedMetrics.costPerUnit !== null
                      ? `₹${formatNum(resolvedMetrics.costPerUnit, 2)}/${resolvedMetrics.primaryUnit}`
                      : "—"}
                  </Text>
                </View>
              </View>
            </View>
          </View>
        )}
      </ScrollView>

      {/* Persistent Bottom Bar */}
      <AppFooter activeTab="SEC" />

      {/* Date Period Picker Modal */}
      <Modal
        visible={dateModalVisible}
        transparent
        animationType="fade"
        onRequestClose={() => {
          setDateModalVisible(false);
          setShowCalendar(false);
        }}
      >
        <TouchableOpacity
          style={styles.modalOverlay}
          activeOpacity={1}
          onPress={() => {
            setDateModalVisible(false);
            setShowCalendar(false);
          }}
        >
          <View
            style={[styles.modalSheet, showCalendar && styles.modalSheetWide]}
            onStartShouldSetResponder={() => true}
          >
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>
                {showCalendar ? "Custom Date Range" : "Select Date Period"}
              </Text>
              <TouchableOpacity
                onPress={() => {
                  if (showCalendar) {
                    setShowCalendar(false);
                    setPickingStep("from");
                  } else {
                    setDateModalVisible(false);
                  }
                }}
              >
                <X size={20} color="#64748B" />
              </TouchableOpacity>
            </View>

            {!showCalendar ? (
              /* Period options list */
              (Object.keys(PERIOD_LABELS) as DatePeriod[]).map((key) => {
                const isSelected = datePeriod === key;
                return (
                  <TouchableOpacity
                    key={key}
                    style={[
                      styles.sortOptionItem,
                      isSelected && styles.sortOptionItemSelected,
                    ]}
                    onPress={() => {
                      if (key === "custom_date") {
                        setPickingStep("from");
                        setShowCalendar(true);
                      } else {
                        setDatePeriod(key);
                        setCustomFrom("");
                        setCustomTo("");
                        setDateModalVisible(false);
                      }
                    }}
                  >
                    <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
                      {key === "custom_date" && (
                        <Calendar size={15} color={isSelected ? "#2563EB" : "#64748B"} />
                      )}
                      <Text
                        style={[
                          styles.sortOptionText,
                          isSelected && styles.sortOptionTextSelected,
                        ]}
                      >
                        {PERIOD_LABELS[key]}
                        {key === "custom_date" && customFrom && customTo
                          ? ` · ${customFrom} → ${customTo}`
                          : ""}
                      </Text>
                    </View>
                    {isSelected && <Check size={18} color="#2563EB" />}
                  </TouchableOpacity>
                );
              })
            ) : (
              /* ── From/To Range Calendar Picker ── */
              <View style={styles.calPickerContainer}>

                {/* Picking step indicator */}
                <View style={styles.calStepRow}>
                  <View style={[styles.calStepPill, pickingStep === "from" && styles.calStepPillActive]}>
                    <Text style={[styles.calStepLabel, pickingStep === "from" && styles.calStepLabelActive]}>
                      FROM
                    </Text>
                    <Text style={[styles.calStepValue, pickingStep === "from" && styles.calStepValueActive]}>
                      {customFrom || "Pick start"}
                    </Text>
                  </View>
                  <Text style={styles.calStepArrow}>→</Text>
                  <View style={[styles.calStepPill, pickingStep === "to" && styles.calStepPillActive]}>
                    <Text style={[styles.calStepLabel, pickingStep === "to" && styles.calStepLabelActive]}>
                      TO
                    </Text>
                    <Text style={[styles.calStepValue, pickingStep === "to" && styles.calStepValueActive]}>
                      {customTo || "Pick end"}
                    </Text>
                  </View>
                </View>

                {/* Month/Year nav */}
                <View style={styles.calNavRow}>
                  <TouchableOpacity
                    style={styles.calNavBtn}
                    onPress={() => {
                      if (calMonth === 0) { setCalMonth(11); setCalYear(calYear - 1); }
                      else setCalMonth(calMonth - 1);
                    }}
                  >
                    <ChevronLeft size={18} color="#1E293B" />
                  </TouchableOpacity>
                  <Text style={styles.calMonthTitle}>
                    {MONTHS_SHORT_SEC[calMonth]} {calYear}
                  </Text>
                  <TouchableOpacity
                    style={styles.calNavBtn}
                    onPress={() => {
                      const now2 = new Date();
                      if (
                        calYear > now2.getFullYear() ||
                        (calYear === now2.getFullYear() && calMonth >= now2.getMonth())
                      ) return;
                      if (calMonth === 11) { setCalMonth(0); setCalYear(calYear + 1); }
                      else setCalMonth(calMonth + 1);
                    }}
                  >
                    <ChevronRight size={18} color="#1E293B" />
                  </TouchableOpacity>
                </View>

                {/* Weekday headers */}
                <View style={styles.calWeekRow}>
                  {WEEKDAYS_SEC.map((w) => (
                    <Text key={w} style={styles.calWeekText}>{w}</Text>
                  ))}
                </View>

                {/* Day cells with range highlight */}
                <View style={styles.calDaysGrid}>
                  {calDaysGrid.map((d, idx) => {
                    if (d === null) {
                      return <View key={`e-${idx}`} style={styles.calDayCellEmpty} />;
                    }
                    const pad2 = (n: number) => String(n).padStart(2, "0");
                    const dateStr = `${calYear}-${pad2(calMonth + 1)}-${pad2(d)}`;
                    const now2 = new Date();
                    const isFuture =
                      calYear > now2.getFullYear() ||
                      (calYear === now2.getFullYear() && calMonth > now2.getMonth()) ||
                      (calYear === now2.getFullYear() && calMonth === now2.getMonth() && d > now2.getDate());

                    const isFrom = dateStr === customFrom;
                    const isTo = dateStr === customTo;
                    const isEndpoint = isFrom || isTo;
                    const isInRange =
                      customFrom && customTo &&
                      cmpDate(dateStr, customFrom) >= 0 &&
                      cmpDate(dateStr, customTo) <= 0;
                    const isToday =
                      calYear === now2.getFullYear() &&
                      calMonth === now2.getMonth() &&
                      d === now2.getDate();

                    return (
                      <TouchableOpacity
                        key={`d-${d}`}
                        style={[
                          styles.calDayCell,
                          isInRange && !isEndpoint && styles.calDayCellInRange,
                          isEndpoint && styles.calDayCellSelected,
                          isToday && !isEndpoint && styles.calDayCellToday,
                          isFuture && styles.calDayCellDisabled,
                        ]}
                        disabled={isFuture}
                        onPress={() => {
                          if (pickingStep === "from") {
                            setCustomFrom(dateStr);
                            setCustomTo("");
                            setPickingStep("to");
                          } else {
                            // If to < from, swap
                            if (customFrom && cmpDate(dateStr, customFrom) < 0) {
                              setCustomTo(customFrom);
                              setCustomFrom(dateStr);
                            } else {
                              setCustomTo(dateStr);
                            }
                            // Stay open — user can still see and hit Apply
                            setPickingStep("from");
                          }
                        }}
                      >
                        <Text
                          style={[
                            styles.calDayText,
                            isEndpoint && styles.calDayTextSelected,
                            isInRange && !isEndpoint && styles.calDayTextInRange,
                            isToday && !isEndpoint && styles.calDayTextToday,
                            isFuture && styles.calDayTextDisabled,
                          ]}
                        >
                          {d}
                        </Text>
                      </TouchableOpacity>
                    );
                  })}
                </View>

                {/* Apply button */}
                <TouchableOpacity
                  style={[
                    styles.calApplyBtn,
                    !(customFrom && customTo) && styles.calApplyBtnDisabled,
                  ]}
                  disabled={!(customFrom && customTo)}
                  onPress={() => {
                    setDatePeriod("custom_date");
                    setShowCalendar(false);
                    setDateModalVisible(false);
                  }}
                >
                  <Text style={styles.calApplyBtnText}>
                    {customFrom && customTo
                      ? `Apply: ${customFrom} → ${customTo}`
                      : pickingStep === "from" ? "Select start date" : "Select end date"}
                  </Text>
                </TouchableOpacity>

                {/* Reset */}
                {(customFrom || customTo) && (
                  <TouchableOpacity
                    style={styles.calResetBtn}
                    onPress={() => {
                      setCustomFrom("");
                      setCustomTo("");
                      setPickingStep("from");
                    }}
                  >
                    <Text style={styles.calResetBtnText}>Reset</Text>
                  </TouchableOpacity>
                )}
              </View>
            )}
          </View>
        </TouchableOpacity>
      </Modal>

      {/* Sort Options Modal */}
      <Modal
        visible={sortModalVisible}
        transparent
        animationType="fade"
        onRequestClose={() => setSortModalVisible(false)}
      >
        <TouchableOpacity
          style={styles.modalOverlay}
          activeOpacity={1}
          onPress={() => setSortModalVisible(false)}
        >
          <View style={styles.modalSheet}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Sort Products</Text>
              <TouchableOpacity onPress={() => setSortModalVisible(false)}>
                <X size={20} color="#64748B" />
              </TouchableOpacity>
            </View>

            {(Object.keys(SORT_LABELS) as SortOption[]).map((key) => {
              const isSelected = sortBy === key;
              return (
                <TouchableOpacity
                  key={key}
                  style={[
                    styles.sortOptionItem,
                    isSelected && styles.sortOptionItemSelected,
                  ]}
                  onPress={() => {
                    setSortBy(key);
                    setSortModalVisible(false);
                  }}
                >
                  <Text
                    style={[
                      styles.sortOptionText,
                      isSelected && styles.sortOptionTextSelected,
                    ]}
                  >
                    {SORT_LABELS[key]}
                  </Text>
                  {isSelected && <Check size={18} color="#2563EB" />}
                </TouchableOpacity>
              );
            })}
          </View>
        </TouchableOpacity>
      </Modal>

      {/* Product Picker Modal */}
      <Modal
        visible={productModalVisible}
        transparent
        animationType="fade"
        onRequestClose={() => setProductModalVisible(false)}
      >
        <TouchableOpacity
          style={styles.modalOverlay}
          activeOpacity={1}
          onPress={() => setProductModalVisible(false)}
        >
          <View style={styles.productPickerSheet}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Select Product</Text>
              <TouchableOpacity onPress={() => setProductModalVisible(false)}>
                <X size={20} color="#64748B" />
              </TouchableOpacity>
            </View>

            {/* Search Box in Modal */}
            <View style={styles.modalSearchBox}>
              <Search size={16} color="#64748B" style={{ marginRight: 8 }} />
              <TextInput
                style={styles.modalSearchInput}
                placeholder="Search by product ID or name..."
                placeholderTextColor="#94A3B8"
                value={productSearchQuery}
                onChangeText={setProductSearchQuery}
              />
            </View>

            <FlatList
              data={sortedProducts}
              keyExtractor={(item, idx) => String(item.productId || item._id || idx)}
              renderItem={({ item }) => {
                const itemId = String(item.productId || item._id);
                const isSelected = itemId === String(selectedProductId);
                const name = item.name || item.productName || "Product";
                const size = item.size ?? "0";

                return (
                  <TouchableOpacity
                    style={[
                      styles.productOptionRow,
                      isSelected && styles.productOptionRowSelected,
                    ]}
                    onPress={() => {
                      setSelectedProductId(itemId);
                      setProductModalVisible(false);
                      setProductSearchQuery("");
                    }}
                  >
                    <View style={styles.productOptionInfo}>
                      <Text
                        style={[
                          styles.productOptionName,
                          isSelected && styles.productOptionNameSelected,
                        ]}
                        numberOfLines={1}
                      >
                        {name}
                      </Text>
                      <Text style={styles.productOptionMeta}>
                        Product ID: {itemId} • Size: {size}
                      </Text>
                    </View>
                    {isSelected && <Check size={18} color="#2563EB" />}
                  </TouchableOpacity>
                );
              }}
            />
          </View>
        </TouchableOpacity>
      </Modal>
    </View>
  );
};

